/// Which kind of resource a hostname claim reserves. Purely descriptive — the
/// authoritative guarantee is the UNIQUE(hostname) on the claim row itself.
enum HostingClaimKind {
  PRIMARY
  SUBDOMAIN
  ADDON
}

/// Single authoritative registry of every hostname served on the fleet, spanning
/// ALL THREE places a name can live — an account's primary domain, a subdomain,
/// or an addon domain. The UNIQUE(hostname) is the atomic cross-tenant guard: a
/// claim row is inserted in the SAME transaction as the resource row it names, so
/// two concurrent requests that both pass the advisory isHostnameClaimed()
/// pre-check can never both commit the same nginx `server_name` — the second
/// INSERT fails on the unique (Prisma P2002) and rolls its whole transaction back.
/// Before this table there was no single constraint spanning the three hostname
/// tables (primaryDomain has no unique), so co-tenants on one node could shadow
/// each other's vhost (security audit: co-tenant vhost-shadowing TOCTOU). The
/// hostname is stored normalized (trimmed + lowercased) so case/format variants
/// can't dodge the unique. Freed by deleting the row when the resource is removed
/// (same tx as the delete / on account termination); the accountId relation also
/// cascades if the account row is ever hard-deleted.
model HostingHostnameClaim {
  id        String           @id @default(cuid())
  hostname  String           @unique
  accountId String
  account   HostingAccount   @relation(fields: [accountId], references: [id], onDelete: Cascade)
  kind      HostingClaimKind
  createdAt DateTime         @default(now())

  @@index([accountId])
}

enum HostingTaskKind {

  status    String    @default("DRAFT") // DRAFT | SENDING | SENT | FAILED
  sentCount Int       @default(0)
  createdAt DateTime  @default(now())
  sentAt    DateTime?
}

// ---- Business email (mailbox hosting per domain) ----
model EmailPlan {
  id            String              @id @default(cuid())
  name          String
  mailboxes     Int                 @default(1) // included mailboxes
  storageGB     Int                 @default(10) // per mailbox
  priceCents    Int
  termMonths    Int                 @default(1)
  active        Boolean             @default(true)
  sortOrder     Int                 @default(0)
  subscriptions EmailSubscription[]
}

model EmailSubscription {
  id                String    @id @default(cuid())
  userId            String
  user              User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  domainName        String
  emailPlanId       String
  emailPlan         EmailPlan @relation(fields: [emailPlanId], references: [id])
  status            String    @default("ACTIVE") // ACTIVE | SUSPENDED | CANCELLED
  verified          Boolean   @default(false)
  verifyToken       String?
  verifiedAt        DateTime?
  external          Boolean   @default(false) // domain registered outside Nxeon
  dkimRecord        String? // cached DKIM TXT value from Mailcow
  autoRenew         Boolean   @default(true)
  /// Billing term this subscription was SOLD on, in months: 1 = monthly, 12 =
  /// annual. The renewal sweep (worker/product-renewals.ts) charges
  /// `termPriceCents(plan monthly, termMonths, annualDiscountPct)` and advances
  /// `expiresAt` this many months, so an annual subscription renews annually at the
  /// sold rate — displayed === charged === renewed. Defaults to 1 so pre-existing
  /// rows keep renewing on their plan's period exactly as before.
  termMonths        Int       @default(1)
  /// PERCENT the ANNUAL discount was set to when THIS subscription's term was sold
  /// — snapshot of `annual_discount_percent` frozen at sale (like
  /// Server.annualDiscountPct). Renewal reads THIS (null → live setting) so an
  /// annual sub renews at the sold rate even if the admin retunes afterwards.
  annualDiscountPct Float?
  createdAt         DateTime  @default(now())
  expiresAt         DateTime?
  mailboxes         Mailbox[]
}

model Mailbox {
  id                 String            @id @default(cuid())
  subscriptionId     String
  subscription       EmailSubscription @relation(fields: [subscriptionId], references: [id], onDelete: Cascade)
  // GLOBALLY unique — every Mailcow call is keyed by this address string on one
  // shared instance, so two rows naming the same address are two customers
  // pointing at ONE real mailbox. That was the data-layer half of the 2026-07-25
  // cross-tenant takeover: an attacker created admin@victim.com under their own
  // subscription and reset "their" password, which rewrote the victim's live
  // mailbox. The application checks are fixed too, but this constraint is what
  // makes the class of bug impossible rather than merely absent today.
  address            String            @unique // full email address
  passwordEnc        String? // encrypted mailbox password (if self-provisioned)
  status             String            @default("PROVISIONING") // PROVISIONING | ACTIVE | SUSPENDED | FAILED
  quotaMB            Int? // mailbox quota in MB (from the plan tier)
  createdAt          DateTime          @default(now())
  signature          String? // legacy / derived plain-text signature (fallback)
  displayName        String?
  autoReplyEnabled   Boolean           @default(false)
  autoReplySubject   String?
  autoReplyBody      String?

