// Shared include for both list + detail lookups: real per-account usage counts
// (databases/addonDomains/subdomains) via Prisma `_count`, plus the plan fields
// the redesigned overview page needs (tier slug/sortOrder for color mapping,
// priceCents/mailboxes for the cost + email columns) — sourced from the DB, never
// fabricated in the view layer.
const HOSTING_ACCOUNT_INCLUDE = {
  plan: { select: { name: true, phpVersions: true, slug: true, sortOrder: true, priceCents: true, mailboxes: true } },
  node: { select: { publicIp: true, hostnameFqdn: true } },
  _count: { select: { databases: true, addonDomains: true, subdomains: true } },
} as const;

export async function listHostingAccounts(): Promise<HostingAccountView[]> {
  const user = await requireUser();
  const rows = await db.hostingAccount.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    include: HOSTING_ACCOUNT_INCLUDE,
  });
  return rows.map(toView);
}

export async function getHostingAccount(id: string): Promise<HostingAccountView | null> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({
    where: { id },
    include: HOSTING_ACCOUNT_INCLUDE,
  });
  if (!a) return null;
  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return toView(a);
}

