const TIER_COLORS: Record<string, { icon: string; badge: string }> = {
  starter: { icon: "bg-gradient-to-br from-brand-500/30 to-brand-600/10 text-brand-300", badge: "border-brand-500/40 bg-brand-500/10 text-brand-300" },
  business: { icon: "bg-gradient-to-br from-teal-500/30 to-emerald-600/10 text-teal-300", badge: "border-teal-500/40 bg-teal-500/10 text-teal-300" },
  pro: { icon: "bg-gradient-to-br from-orange-500/30 to-orange-600/10 text-orange-300", badge: "border-orange-500/40 bg-orange-500/10 text-orange-300" },
};
const TIER_COLOR_RAMP = [
  { icon: "bg-gradient-to-br from-brand-500/30 to-brand-600/10 text-brand-300", badge: "border-brand-500/40 bg-brand-500/10 text-brand-300" },
  { icon: "bg-gradient-to-br from-accent-blue/30 to-blue-600/10 text-blue-300", badge: "border-blue-500/40 bg-blue-500/10 text-blue-300" },
  { icon: "bg-gradient-to-br from-teal-500/30 to-emerald-600/10 text-teal-300", badge: "border-teal-500/40 bg-teal-500/10 text-teal-300" },
  { icon: "bg-gradient-to-br from-orange-500/30 to-orange-600/10 text-orange-300", badge: "border-orange-500/40 bg-orange-500/10 text-orange-300" },
];
function tierColor(a: Pick<HostingAccountView, "planSlug" | "planSortOrder">) {
  return TIER_COLORS[a.planSlug] ?? TIER_COLOR_RAMP[a.planSortOrder % TIER_COLOR_RAMP.length];
}

function fmtDate(iso: string | null): string {
  if (!iso) return "—";
  return new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}

/** Real per-cycle charge + its unit label — never hardcoded to "/month". Uses the
 *  SAME formula the renewal sweep actually bills (lib/billing-terms.termPriceCents)
 *  against the term + discount this account was SOLD on, so the number shown here
 *  matches what the customer is really charged at renewal. */
function termLabel(months: number): string {
  if (months === 1) return "/ month";
  if (months % 12 === 0) return months === 12 ? "/ year" : `/ ${months / 12} years`;
  return `/ ${months} mo`;
}

function pct(used: number, total: number): number {
  if (!total || total <= 0) return 0;
  return Math.max(0, Math.min(100, (used / total) * 100));
}

/** Extra sites (subdomains + addon domains) vs the plan's site budget — the exact
 *  same "extra sites" metric already shown on the account detail page's Overview
 *  tab (components/customer/hosting/HostingTabs.tsx QuotaTile), just aggregated /
 *  reused here. The primary domain is always live and isn't counted against the
 *  budget, matching that existing convention. */
function siteUsage(a: HostingAccountView) {
  return { used: a.subdomainsUsed + a.addonDomainsUsed, total: a.maxSites };
}
function dbUsage(a: HostingAccountView) {
  return { used: a.databasesUsed, total: a.maxDatabases };
}
function storageUsageMB(a: HostingAccountView) {
  return { used: a.diskUsedMB ?? 0, total: a.diskQuotaMB, measured: a.diskUsedMB != null };
}

/* ---------------------------------------------------------------- widget --- */

function MiniUsage({
  icon,
  label,
  used,
  total,
  color,
  unlimited = false,
  noUsageNote,
  format,
}: {
  icon: React.ReactNode;
  label: string;
  used: number;
  total: number;
  color: string;
  unlimited?: boolean;
  /** Set when there is no real "used" number for this dimension — renders the
   *  total only, with a note, and skips the bar rather than fabricating a used
   *  value. */
  noUsageNote?: string;
  format?: (n: number) => string;
}) {
  const f = format ?? ((n: number) => String(n));
  return (
    <div className="min-w-[92px]" title={noUsageNote}>
      <div className="flex items-center gap-1 text-[10px] font-medium uppercase tracking-wide text-slate-500">
        <span className="h-3 w-3 text-slate-500">{icon}</span>
        {label}
      </div>
      <div className="mt-0.5 text-xs font-semibold text-slate-200">
        {unlimited ? "Unlimited" : noUsageNote ? `${f(total)} incl.` : `${f(used)} / ${f(total)}`}
      </div>
      {!unlimited && !noUsageNote && (
        <div className="mt-1 w-20">
          <MeterBar value={used} max={total || 1} color={color} className="h-1.5" />
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ menu --- */

function RowMenu({
  a,
  onRetry,
  onRecheck,
}: {
  a: HostingAccountView;
  onRetry: () => void;
  onRecheck: () => void;
}) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function onDoc(e: MouseEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open]);

  const itemClass = "block w-full rounded-lg px-3 py-1.5 text-left text-xs text-slate-300 hover:bg-white/[0.06] hover:text-white";

  return (
    <div ref={ref} className="relative" onClick={(e) => e.stopPropagation()}>
      <button
        type="button"
        aria-label="Account actions"
        className="rounded-lg p-1.5 text-slate-500 hover:bg-white/[0.06] hover:text-white"
        onClick={() => setOpen((o) => !o)}
      >
        <IconDotsVertical className="h-4 w-4" />
      </button>
      {open && (
        <div className="absolute right-0 top-full z-20 mt-1 w-48 rounded-xl border border-white/10 bg-navy-900 p-1.5 shadow-2xl">
          <a href={`/dashboard/hosting/${a.id}`} className={itemClass}>Manage</a>
          {a.status === "ACTIVE" && (
            <a href={`https://${a.primaryDomain}`} target="_blank" rel="noreferrer" className={itemClass}>
              Visit site ↗
            </a>
          )}
          {a.status === "ACTIVE" && (
            <button type="button" className={itemClass} onClick={() => { setOpen(false); onRecheck(); }}>
              Check now / Go live
            </button>
          )}
          {a.status === "FAILED" && (
            <button type="button" className={itemClass} onClick={() => { setOpen(false); onRetry(); }}>
              Retry setup
            </button>
          )}
          <a href={`/dashboard/hosting/${a.id}?tab=settings`} className={`${itemClass} text-red-300 hover:text-red-200`}>
            Cancel account
          </a>
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------- row --- */

function PlanRow({
  a,
  onRetry,
  onRecheck,
}: {
  a: HostingAccountView;
  onRetry: () => void;
  onRecheck: () => void;
}) {
  const router = useRouter();
  const tier = tierColor(a);
  const sites = siteUsage(a);
  const dbs = dbUsage(a);
  const storage = storageUsageMB(a);
  const cycleCents = termPriceCents(a.planPriceCents, a.termMonths, a.annualDiscountPct ?? undefined);

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={() => router.push(`/dashboard/hosting/${a.id}`)}
      onKeyDown={(e) => {
        if (e.key === "Enter") router.push(`/dashboard/hosting/${a.id}`);
      }}
      className="grid cursor-pointer grid-cols-1 gap-4 p-4 transition-colors hover:bg-white/[0.03] sm:p-5 md:grid-cols-[minmax(190px,1.5fr)_minmax(280px,2fr)_120px_110px_100px_28px] md:items-center md:gap-3"
    >
      {/* Plan */}
      <div className="flex items-start gap-3">
        <div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${tier.icon}`}>
          <IconGlobe className="h-5 w-5" />
        </div>
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            {/* HostingAccount has no separate customer-set label field — the display
                name IS the primary domain (see report). */}
            <span className="truncate font-semibold text-slate-100">{a.primaryDomain}</span>
            <span className={`inline-flex items-center rounded-full border px-2 py-0.5 text-[10px] font-medium ${tier.badge}`}>
              {a.planName}
            </span>
          </div>
          <a
            href={`https://${a.primaryDomain}`}
            target="_blank"
            rel="noreferrer"
            onClick={(e) => e.stopPropagation()}
            className="mt-0.5 inline-flex items-center gap-1 text-xs text-slate-500 hover:text-brand-300 hover:underline"
          >
            {a.primaryDomain}
            <IconExternal className="h-3 w-3" />
          </a>
        </div>
      </div>

      {/* Usage */}
      <div className="flex flex-wrap gap-4">
        <MiniUsage icon={<IconGlobe />} label="Sites" used={sites.used} total={sites.total} color="#8a70fb" />
        <MiniUsage icon={<IconDb />} label="DBs" used={dbs.used} total={dbs.total} color="#3b82f6" />
        <MiniUsage
          icon={<IconDisk />}
          label="Storage"
          used={storage.used / 1024}
          total={storage.total / 1024}
          color="#22d3ee"
          format={(n) => n.toFixed(n < 10 ? 1 : 0)}
          noUsageNote={storage.measured ? undefined : "Not measured yet — updates once the account is live"}
        />
        <MiniUsage
          icon={<IconMail />}
          label="Mail"
          used={0}
          total={a.planMailboxes}
          color="#fb923c"
          unlimited={a.planMailboxes === -1}
          noUsageNote={a.planMailboxes === -1 ? undefined : "Mailbox usage isn't tracked for shared hosting yet — included allowance shown"}
        />
      </div>

      {/* Renewal */}
      <div className="flex items-center gap-1.5 text-xs text-slate-400">
        <IconCalendar className="h-3.5 w-3.5 shrink-0 text-slate-500" />
        {fmtDate(a.expiresAt)}
      </div>

      {/* Status */}
      <div>
        <StatusDot status={a.status} />
      </div>

      {/* Cost */}
      <div className="flex items-baseline gap-1">
        <span className="text-sm font-bold text-slate-100">{fmtMoney(cycleCents)}</span>
        <span className="text-[11px] text-slate-500">{termLabel(a.termMonths)}</span>
      </div>

      {/* Actions */}
      <div className="flex justify-end">
        <RowMenu a={a} onRetry={onRetry} onRecheck={onRecheck} />
      </div>
    </div>
  );
}

/* ----------------------------------------------------------------- stats --- */

function SummaryCell({
  icon,
  label,
  value,
  pctValue,
  color,
  note,
  statusDot,
}: {
  icon: React.ReactNode;
  label: string;
  value: React.ReactNode;
  pctValue?: number;
  color?: string;
  note?: string;
  statusDot?: boolean;
}) {
  return (
    <div className="p-5">
      <div className="flex items-center gap-2 text-slate-400">
        <span className="flex h-8 w-8 items-center justify-center rounded-lg border border-white/[0.08] bg-white/[0.03] text-brand-300">
          <span className="h-4 w-4 [&>svg]:h-4 [&>svg]:w-4">{icon}</span>
        </span>
        <span className="text-xs font-medium uppercase tracking-wide">{label}</span>
      </div>
      <div className="mt-2 flex items-center gap-2">
        <span className="text-xl font-bold tracking-tight text-slate-100">{value}</span>
        {statusDot && <span className="h-2 w-2 rounded-full bg-emerald-400" />}
      </div>
      {pctValue != null && color && (
        <div className="mt-2">
          <MeterBar value={pctValue} max={100} color={color} className="h-1.5" />
        </div>
      )}
      {note && <p className="mt-1 text-[10px] text-slate-500">{note}</p>}
    </div>
  );
}

/* ----------------------------------------------------------------- main --- */

export function HostingClient({ accounts }: { accounts: HostingAccountView[] }) {
  const [error, setError] = useState("");
  const [tab, setTab] = useState<Tab>("all");
  const [query, setQuery] = useState("");
  const [tierFilter, setTierFilter] = useState<string | null>(null);
  const [filterOpen, setFilterOpen] = useState(false);
  const [page, setPage] = useState(1);
  const filterRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!filterOpen) return;
    function onDoc(e: MouseEvent) {
      if (filterRef.current && !filterRef.current.contains(e.target as Node)) setFilterOpen(false);
    }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [filterOpen]);

  async function retry(id: string) {
    setError("");
    const res = await retryHostingProvision(id);
    if (res.error) {
      setError(res.error);
      return;
    }
    window.location.reload();
  }

  async function recheck(id: string) {
    setError("");
    const res = await recheckHostingHealth(id);
    if (res.error) {
      setError(res.error);
      return;
    }
    window.location.reload();
  }

  const tiers = useMemo(() => Array.from(new Set(accounts.map((a) => a.planName))).sort(), [accounts]);

  // Bucket mapping for the tabs: HostingAccountStatus has no literal "EXPIRED"
  // state — an unpaid/past-due account is flipped to SUSPENDED by the renewal
  // sweep (worker/product-renewals.ts suspendUnpaidHostingAccount), so "Expired"
  // == SUSPENDED. PENDING/PROVISIONING/FAILED/DELETING accounts show under "All
  // Plans" only (they're neither a healthy active plan nor a lapsed one).
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return accounts.filter((a) => {
      if (tab === "active" && a.status !== "ACTIVE") return false;
      if (tab === "expired" && a.status !== "SUSPENDED") return false;
      if (tierFilter && a.planName !== tierFilter) return false;
      if (q && !a.primaryDomain.toLowerCase().includes(q) && !a.planName.toLowerCase().includes(q)) return false;
      return true;
    });
  }, [accounts, tab, tierFilter, query]);

  useEffect(() => {
    setPage(1);
  }, [tab, tierFilter, query]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const clampedPage = Math.min(page, totalPages);
  const pageRows = filtered.slice((clampedPage - 1) * PAGE_SIZE, clampedPage * PAGE_SIZE);

  // Fleet-wide summary — always over ALL of the customer's accounts (not the
  // current tab/search filter), so it reads as a stable "your whole hosting
  // footprint" tile rather than shifting under a filter.
  const activeCount = accounts.filter((a) => a.status === "ACTIVE").length;
  const sitesTotal = accounts.reduce((s, a) => s + siteUsage(a).total, 0);
  const sitesUsed = accounts.reduce((s, a) => s + siteUsage(a).used, 0);
  const dbTotal = accounts.reduce((s, a) => s + dbUsage(a).total, 0);
  const dbUsed = accounts.reduce((s, a) => s + dbUsage(a).used, 0);
  const storageTotalGB = accounts.reduce((s, a) => s + a.diskQuotaMB, 0) / 1024;
  const storageUsedGB = accounts.reduce((s, a) => s + (a.diskUsedMB ?? 0), 0) / 1024;
  const hasUnmeasuredStorage = accounts.some((a) => a.status === "ACTIVE" && a.diskUsedMB == null);
  const mailUnlimited = accounts.some((a) => a.planMailboxes === -1);
  const mailTotal = accounts.reduce((s, a) => s + Math.max(0, a.planMailboxes), 0);

  if (accounts.length === 0) {
    return (
      <div className="space-y-8">
        {error && <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
        <EmptyState
          title="No hosting accounts yet"
          sub="Set up an isolated hosting account — on a free subdomain or your own domain — in a couple of minutes."
          action={<DeployButton href="/dashboard/deploy?product=hosting">Deploy your first site</DeployButton>}
        />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {error && <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}

      {/* Summary stat card */}
      <div className="card overflow-hidden p-0">
        <div className="grid divide-y divide-white/[0.06] sm:grid-cols-2 sm:divide-x sm:divide-y-0 lg:grid-cols-5">
          <SummaryCell icon={<IconStack />} label="Active Plans" value={activeCount} statusDot />
          <SummaryCell
            icon={<IconGlobe />}
            label="Websites"
            value={`${sitesUsed} / ${sitesTotal}`}
            pctValue={pct(sitesUsed, sitesTotal)}
            color="#8a70fb"
          />
          <SummaryCell
            icon={<IconDb />}
            label="Databases"
            value={`${dbUsed} / ${dbTotal}`}
            pctValue={pct(dbUsed, dbTotal)}
            color="#3b82f6"
          />
          <SummaryCell
            icon={<IconDisk />}
            label="Storage"
            value={`${storageUsedGB.toFixed(storageUsedGB < 10 ? 1 : 0)} / ${storageTotalGB.toFixed(0)} GB`}
            pctValue={pct(storageUsedGB, storageTotalGB)}
            color="#22d3ee"
            note={hasUnmeasuredStorage ? "Some accounts are still measuring usage" : undefined}
          />
          <SummaryCell
            icon={<IconMail />}
            label="Emails"
            value={mailUnlimited ? "Unlimited" : `${mailTotal} incl.`}
            note="Mailbox usage isn't tracked for shared hosting yet"
          />
        </div>
      </div>

      {/* Tabs + search row */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex gap-1 rounded-xl border border-white/[0.08] bg-white/[0.03] p-1">
          {([
            { key: "all", label: "All Plans" },
            { key: "active", label: "Active" },
            { key: "expired", label: "Expired" },
          ] as { key: Tab; label: string }[]).map((t) => (
            <button
              key={t.key}
              type="button"
              onClick={() => setTab(t.key)}
              className={`rounded-lg px-3 py-1.5 text-xs font-semibold transition-colors ${
                tab === t.key ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white" : "text-slate-400 hover:text-white"
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-2">
          <div className="relative">
            <IconSearch className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" />
            <input
              type="search"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search plans..."
              className="input w-52 py-2 pl-9"
            />
          </div>
          <div className="relative" ref={filterRef}>
            <button
              type="button"
              aria-label="Filter by tier"
              onClick={() => setFilterOpen((o) => !o)}
              className={`btn-secondary p-2 ${tierFilter ? "border-brand-500/50 text-brand-300" : ""}`}
            >
              <IconSliders className="h-4 w-4" />
            </button>
            {filterOpen && (
              <div className="absolute right-0 top-full z-20 mt-1 w-44 rounded-xl border border-white/10 bg-navy-900 p-1.5 shadow-2xl">
                <button
                  type="button"
                  className={`block w-full rounded-lg px-3 py-1.5 text-left text-xs ${!tierFilter ? "bg-white/[0.06] text-white" : "text-slate-300 hover:bg-white/[0.06] hover:text-white"}`}
                  onClick={() => { setTierFilter(null); setFilterOpen(false); }}
                >
                  All tiers
                </button>
                {tiers.map((t) => (
                  <button
                    key={t}
                    type="button"
                    className={`block w-full rounded-lg px-3 py-1.5 text-left text-xs ${tierFilter === t ? "bg-white/[0.06] text-white" : "text-slate-300 hover:bg-white/[0.06] hover:text-white"}`}
                    onClick={() => { setTierFilter(t); setFilterOpen(false); }}
                  >
                    {t}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="card overflow-hidden p-0">
        {pageRows.length === 0 ? (
          <div className="p-10 text-center text-sm text-slate-400">No hosting plans match your filters.</div>
        ) : (
          <div className="divide-y divide-white/[0.06]">
            {pageRows.map((a) => (
              <PlanRow key={a.id} a={a} onRetry={() => retry(a.id)} onRecheck={() => recheck(a.id)} />
            ))}
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="flex flex-wrap items-center justify-between gap-3 text-xs text-slate-500">
        <span>
          Showing {pageRows.length ? (clampedPage - 1) * PAGE_SIZE + 1 : 0}–{(clampedPage - 1) * PAGE_SIZE + pageRows.length} of{" "}
          {filtered.length} plan{filtered.length === 1 ? "" : "s"}
        </span>
        {totalPages > 1 && (
          <div className="flex items-center gap-2">
            <button
              type="button"
              className="btn-ghost px-2 py-1 disabled:opacity-30"
              disabled={clampedPage <= 1}
              onClick={() => setPage((p) => p - 1)}
            >
              Prev
            </button>
            <span>
              {clampedPage} / {totalPages}
            </span>
            <button
              type="button"
              className="btn-ghost px-2 py-1 disabled:opacity-30"
              disabled={clampedPage >= totalPages}
              onClick={() => setPage((p) => p + 1)}
            >
              Next
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

